/*
 * @the_tree/esbuild-plugin-vue3 0.3.1 hashes its native relative path for
 * Vue scope IDs and embeds that path in the generated component module. Keep
 * those generated bytes stable across Windows and POSIX builders.
 */
const fs = require("node:fs");
const path = require("node:path");

const packageJson = path.resolve(__dirname, "../node_modules/@the_tree/esbuild-plugin-vue3/package.json");
const sourcePath = path.resolve(__dirname, "../node_modules/@the_tree/esbuild-plugin-vue3/dist/index.js");
const expectedVersion = "0.3.1";
const before = 'filename = path.relative(process.cwd(), args.path);';
const after = 'filename = path.relative(process.cwd(), args.path).replace(/\\\\/g, "/");';

if (!fs.existsSync(packageJson) || !fs.existsSync(sourcePath)) {
  throw new Error("@the_tree/esbuild-plugin-vue3 0.3.1 is not installed; run npm ci first");
}

const installed = JSON.parse(fs.readFileSync(packageJson, "utf8"));
if (installed.version !== expectedVersion) {
  throw new Error(`Unsupported @the_tree/esbuild-plugin-vue3 version ${installed.version}; expected ${expectedVersion}`);
}

const source = fs.readFileSync(sourcePath, "utf8");
const originalCount = source.split(before).length - 1;
const patchedCount = source.split(after).length - 1;
if (originalCount === 0 && patchedCount === 1) {
  console.log("Vue SFC path patch already applied");
  process.exit(0);
}
if (originalCount !== 1 || patchedCount !== 0) {
  throw new Error(`Unexpected @the_tree/esbuild-plugin-vue3 source: ${originalCount} original and ${patchedCount} patched path assignments`);
}
fs.writeFileSync(sourcePath, source.replace(before, after));
console.log("Vue SFC path patch applied");
